css:
#loader-31 {
  width: 60px;
  height: 16px;
  display: flex;
  justify-content: space-between;
  animation: l3-0 2s infinite alternate;
}
#loader-31:before,
#loader-31:after {
  content: "";
  width: 16px;
  background: #3FB8AF;
  animation: l3-1 1s infinite alternate;
}
#loader-31:after {
  background: #FF3D7F;
  --s:-1;
}
@keyframes l3-0 {
   0%,40%   {transform: rotate(0)}
   80%,100% {transform: rotate(.5turn)}
}
@keyframes l3-1 {
   80%,100% {transform: translate(calc(var(--s,1)*14px))}
}
